(function () { const searchInput = document.getElementById('admin-function-search'); const chips = Array.from(document.querySelectorAll('[data-section-filter]')); const sections = Array.from(document.querySelectorAll('[data-admin-section]')); const emptyState = document.getElementById('admin-functions-empty'); if (!searchInput || !sections.length) return; let activeSection = 'all'; function normalize(value) { return String(value || '') .normalize('NFD') .replace(/[\u0300-\u036f]/g, '') .toLowerCase() .trim(); } function updateChipState() { chips.forEach(function (chip) { const active = String(chip.dataset.sectionFilter || 'all') === activeSection; chip.classList.toggle('is-active', active); chip.setAttribute('aria-pressed', active ? 'true' : 'false'); }); } function applyFilters() { const query = normalize(searchInput.value); let visibleSections = 0; sections.forEach(function (section) { const sectionId = String(section.dataset.sectionId || ''); const cards = Array.from(section.querySelectorAll('[data-admin-item]')); let visibleCards = 0; cards.forEach(function (card) { const matchesSection = activeSection === 'all' || sectionId === activeSection; const haystack = normalize(card.dataset.adminSearch || ''); const matchesQuery = !query || haystack.includes(query); const visible = matchesSection && matchesQuery; card.hidden = !visible; if (visible) visibleCards += 1; }); const count = section.querySelector('[data-visible-count]'); if (count) count.textContent = String(visibleCards); const showSection = visibleCards > 0; section.hidden = !showSection; if (showSection) visibleSections += 1; }); if (emptyState) emptyState.hidden = visibleSections !== 0; } searchInput.addEventListener('input', applyFilters); chips.forEach(function (chip) { chip.addEventListener('click', function () { activeSection = String(chip.dataset.sectionFilter || 'all'); updateChipState(); applyFilters(); }); }); updateChipState(); applyFilters(); })();